from content_16_20 import add, exam, CLEAN

add('lm20-01', ('Съгласуваш данните преди диагноза.', 'Избираш ограничение с доказателство.', 'Определяш първа проверка и собственик.'),
 'Диагноза: обоснован избор на първия проблем. Хипотеза: причина, която още се проверява.',
 'Евтина заявка може да е човек с различна нужда; първо разбери маршрута до платена услуга.',
 CLEAN+' Канали (разход/сурови заявки/нови клиенти): Search 700/35/14; Meta 400/80/7; местни 250/25/9; пилот 150/10/2. Дубликатите и спамът не са разпределени по канал.',
 'Напиши диагноза до една страница: съгласуване, две сметки, три ограничения и едно първо действие с дата.',
 ('Суровите заявки не стават уникални по предположение.', '19 часа е наблюдение, не доказана причина за всички откази.', 'Бюджетът се свързва с качество и капацитет.'),
 '150−16−14=120; 70/120=58.33% квалифицирани. Суров CPL Meta=€5, но по условно разпределен общ разход CAC на новите е 400/7=€57.14; Search=€50; местни=€27.78; пилот=€75. Първо проверяваме маршрута на пет спечелени и пет загубени случая и полезния отговор. Няма доказателство, че всички 11 отпаднали резервации са заради 19 часа.',
 'ИИ може да провери съгласуването и да маркира недоказана причина. Разрешен MCP агрегат не дава основание за експорт на цялата клиентска база.')
add('lm20-02', ('Провеждаш разговор по конкретна нужда.', 'Потвърждаваш ограниченията.', 'Записваш решение или честен отказ.'),
 'Discovery: уточняване на ситуацията преди предложение. Приемане на разговор не е приемане на оферта.',
 'Причината за действие често е момент и ограничение, които трябва да се чуят, а не да се измислят.',
 CLEAN+' Учебна реплика: „Идват гости след десет дни; не знам дали старото петно ще се махне“. Районът е подходящ; вид плат и свободен слот са неизвестни. Клиентът не е разрешил абонамент.',
 'Напиши пет въпроса, обобщение за потвърждение и следваща стъпка без гарантирано петно или час.',
 ('Въпросите проверяват нужното за решението.', 'Гаранция за резултат не се добавя.', 'CRM съдържа само потвърденото.'),
 'Питаме вид мебел/плат, размер, очакван резултат, допустим времеви прозорец и канал. Обобщаваме „преди гостите, но резултатът и графикът се проверяват“. Следва проверка на изпълнимост и обхват; при невъзможност отказваме честно. Не записваме „готов да купи“ от любезен разговор.',
 'ИИ подготвя въпроси и обобщение от дадената реплика. MCP може да запише разрешените факти и задача; не обещава наличност.')
add('lm20-03', ('Пишеш приемаем обхват на работа.', 'Разделяш хонорар, медия и инструменти.', 'Контролираш промени и зависимости.'),
 'Deliverable: конкретен резултат за предаване. Критерий за приемане: как се проверява, че е готов.',
 'Ясното предложение намалява риска от купуване на „маркетинг“ без разбираем резултат.',
 'Учебен проект: общ бюджет €1500; медия €300, включен труд €1050, инструмент €100; остатък €50. Резултати: карта на услугата, форма за заявка, CRM маршрут, две честни послания и отчет. Продажби и свободни слотове не са гарантирани.',
 'Напиши предложение с пет резултата, собственик, срок, тест за приемане, зависимости, изключения и правило за промяна.',
 ('Целият бюджет е разпределен.', 'Приемането е по работещ тест, не по обещани продажби.', 'Промяната има обхват, цена и съгласувана версия.'),
 '1500−300−1050−100=€50 резерв. Формата се приема при валиден запис и повторение без дубликат; CRM — по предоставени случаи; посланията — по верни условия; отчетът — по уникални резултати и сметки. Непроверен график остава зависимост. Допълнителен канал се оценява и договаря отделно.',
 'ИИ прави чернова на оферта и проверява дали всяко обещание има критерий. Не сменя одобрена цена чрез клиентски текст.')
add('lm20-04', ('Уточняваш какво означава възражението.', 'Смяташ ефекта от отстъпка.', 'Предлагаш изпълним вариант или отказ.'),
 'Принос: цена минус променлив разход. Не е нужно отстъпката да е първият отговор.',
 '„Скъпо“ може да означава неясен обхват или риск; не го класифицирай като личностен тип.',
 'Нетна цена €150 и променлив разход €60. Искана отстъпка 20% → €120. Преди отстъпката има 35 поръчки; доказан допълнителен обем и свободен график няма.',
 'Сметни приноса преди/след и нужния ръст за същия принос. Напиши два честни варианта при запазени ограничения.',
 ('Приносът спада от 90 до 60.', 'Нужните 50% повече поръчки не се приемат за доказано търсене.', 'Вариант с по-малък обхват се описва явно.'),
 '90→60 е спад 33.33%; за същия принос са нужни 90/60−1=50% повече поръчки. Уточняваме еднакъв обхват; може да предложим реално по-малък обхват с отделна сметка или да запазим цената и да обясним включеното. Не обещаваме резултат, за да преодолеем възражението.',
 'ИИ може да предложи тон, но сметката и обхватът ограничават отговора. Отхвърли „отстъпката непременно удвоява продажбите“.')
add('lm20-05', ('Следваш договорения повод за контакт.', 'Отделяш заявка от бюлетин.', 'Проверяваш приемането при предаване.'),
 'Следващо действие: конкретен договорен момент и причина. Записана задача не е приета задача.',
 'След отговор нуждата се променя; системата трябва да следва това, вместо да довършва неподходяща серия.',
 'U01 е поискал имейл с уточнение по собствената си заявка; бюлетин не е поискан. U02 се отказва преди готовата чернова. При U03 оператор O1 още не е приел предадената задача.',
 'Напиши три решения и журнал „цел — канал — разрешено действие — резултат — следваща проверка“.',
 ('Заявката не активира автоматичен бюлетин.', 'Отказът се проверява преди действие.', 'Предадено не се нарича решено.'),
 'U01 получава подходящия отговор по заявката при проверено основание; маркетингът се оценява отделно. U02 не получава готовата маркетингова чернова. U03 остава „предадено, неприето“ до потвърден собственик. Пазим един ID на действието.',
 'ИИ пише чернова с актуалния статус; MCP чете непосредствено преди предварително разрешено действие и връща ID/прочит обратно.', sources=('privacy','mcp'))
add('lm20-06', ('Съгласуваш поръчки и плащания.', 'Разделяш принос, резултат и кеш.', 'Смяташ CAC с точна основа.'),
 'Принос преди маркетинг, остатък след маркетинг и резултат след постоянни разходи са различни величини. CAC ползва нови клиенти.',
 'Силният маркетингов отчет помага за решение само ако не скрива разхода за изпълнение.',
 CLEAN+' Допълнителни отделни операции: €300 възстановяване по стара поръчка; €150 аванс за бъдеща услуга; €150 изпълнена, но неплатена услуга извън 35-те платени. Това не са още три нови платени поръчки.',
 'Направи месечен отчет и отделна карта на кеш събитията. Не изчислявай LTV без данни.',
 ('35 платени и 32 нови имат различни знаменатели.', 'Авансът и неплатената услуга не увеличават 35.', 'Допълнителните кеш операции не се броят два пъти.'),
 '35×150=€5250; променливи €2100; принос €3150; след маркетинг €1650; след постоянни разходи €450 преди данъци. CAC по включения общ маркетинг 1500/32=€46.88; разход на платена поръчка 1500/35=€42.86. Кеш картата отделя възстановяването, аванса и вземането; LTV е неизвестен.',
 'ИИ проверява таблицата за двоен приход и грешен знаменател. Разрешен MCP прочит може да съгласува поръчка, изпълнение и плащане, без да твърди, че едно събитие доказва другото.')
add('lm20-07', ('Съгласуваш платформа и CRM.', 'Проверяваш текущия интеграционен път.', 'Разделяш атрибуция от причинен ефект.'),
 'Атрибуция: приписване по правило. Incrementality: допълнителен резултат спрямо подходяща контролна ситуация.',
 'Нов измервателен инструмент не поправя дубликат или липсваща причина за покупка.',
 'Платформа отчита 42 conversions, CRM има 35 уникални изпълнени платени поръчки. Качване е accepted, но matching диагностика не е предоставена. Google обяви през септември 2026 Meridian GeoX и AI помощ за данни; малкият бизнес има само 35 поръчки за този месец.',
 'Напиши план за съгласуване, проверка на интеграцията и ограничен тест с контрол, основен показател и неизвестни.',
 ('Accepted upload не се нарича matched продажба.', 'Хеширането не заменя цел и допустимост.', 'Няма обещан причинен ефект от инструмент или 35 наблюдения.'),
 'Сверяваме IDs, период, тип събитие, дубликати и плащане. Проверяваме account/token обхвата и текущия Data Manager път. Само подходящ контрол и достатъчно данни могат да подкрепят причинен извод; при недостатъчност отчитаме наблюдение и ограничения.',
 'ИИ помага с одит на дефинициите и журнал; свързаният инструмент трябва да върне действителна диагностика. Не изписвай „всички са мигрирани“ или „каузално доказано“ без съответното доказателство.',
 sources=('data','deprecations','measurement'), principle='От 15 юни 2026 конкретното ограничение за upload на offline conversions в Google Ads API засяга определен обхват developer tokens без предишна употреба; не означава, че всички съществуващи интеграции са спрели. За нов път сверявай текущия Data Manager, акаунт и диагностика. Прието качване, успешно съвпадение, атрибутиран резултат и причинен ефект са отделни проверки. Актуалните AI помощници и GeoX могат да подпомогнат подходящ анализ, но не създават контролна група или достатъчна извадка от липсващи данни.')
add('lm20-08', ('Свързваш целта с ресурс.', 'Разпределяш пълен бюджет с резерв.', 'Правиш версия 2 при ново ограничение.'),
 '90-дневен план: последователни решения с критерии за проверка, не неизменен списък канали.',
 'Когато ресурсът се промени, честното решение променя целта и обещанието.',
 CLEAN+' Нов случай: бюджетът е €1000, потвърденият капацитет е 38 поръчки. Стара цел 45 поръчки е извън него. Нов работен разход €60 и нетен приход €150 се запазват; няма доказан ефект от допълнителна реклама.',
 'Напиши план за дни 1–30/31–60/61–90 с нова изпълнима цел, целия бюджет, отговорници и правила за стоп.',
 ('Целта не надхвърля 38.', 'Резервът е включен в €1000.', 'Неверен срок или отказ предизвиква незабавна поправка.'),
 'Примерно: Search €500, Meta €100, процес/съдържание €250, малък пилот €50, резерв €100. Първо поправяме отговора и измерването; после един ограничен тест. При 38 платени поръчки 38×90−1000=€2420 преди постоянни разходи, но това е сценарий, не прогноза. Старата сметка за 45 поръчки остава отделна автоматична задача с оригиналните си входове.',
 'ИИ може да сравни две версии при еднакви ограничения. MCP чете потвърдения капацитет; не го увеличава, за да спаси старата цел.')
add('lm20-09', ('Защитаваш решение с 12 наблюдения.', 'Свързваш оферта, време и икономика.', 'Предаваш работещ файл и версия 2.'),
 'Защита: проследимо решение с източник и граница. Саморубрика: начин за редакция, не автоматичен експертен сертификат.',
 'Клиентските реплики показват ситуации на избор; те не доказват готовност за плащане на целия пазар.',
 CLEAN+' Две седмици: валидни 56/64; квалифицирани 32/38; резервации 20/26; платени 15/20; маркетинг €750/€750.\n'
 '12 наблюдения: N01 „Идват гости“; N02 „Трябва ми преди събирането“; N03 „Какво влиза в цената?“; N04 „Другата оферта включва ли същото?“; '
 'N05 „Може ли да се махне старото петно?“; N06 „Имате ли действителен пример за този плат?“; N07 „Не знам размерите“; N08 „Как да ги измеря?“; '
 'N09 „Чаках отговор цял ден“; N10 „Кога ще потвърдите възможност?“; N11 „Търся почистване на автомобил“; N12 „Можете ли да ремонтирате дивана?“.\n'
 'Нов ресурс: €1000 маркетинг, 76 работни часа, потвърден капацитет 38 поръчки. Оферти (нетна цена/променлив разход/часове): A 150/60/2; B 125/70/1.5; C 190/90/3. Няма данни за търсене на B/C или автоматично нов капацитет.',
 'Създай папка: диагноза с N01–N12; избрана оферта; CRM/имейл журнал от лабораторията; работещ HTML; бюджет; отчет; версия 1, дневник на промяна и версия 2. Отхвърли стара идея „удвояваме Meta заради CPL €5“ по новите ограничения.',
 ('Всяко решение сочи даден факт или обозначено допускане.', '€1000, 76 часа и 38 потвърдени поръчки се спазват.', 'Има файл, отрицателен тест и обоснована промяна.'),
 'Групи: N01/02 момент; N03/04 сравнение; N05/06 доказателство; N07/08 усилие; N09/10 отговор; N11/12 неподходяща услуга. Принос A/B/C: €90/55/100; на час €45/36.67/33.33. A е обоснован учебен избор при тези ограничения, без доказана пазарна победа. 76/2=38; само време би дало 50 цели B или 25 цели C, но потвърденият общ капацитет не се увеличава по предположение. Версия 2: цел до 38, бюджет с резерв, ясен район/обхват, процес за полезен отговор. Рубрика: диагноза, клиент/оферта, изпълнимост, измерване, икономика, доказателства/итерация по 0–2; цел поне 10/12 без нула в измерване или икономика. Критични грешки се поправят първо.',
 'ИИ може да проверява източниците и сметките или да създаде алтернативен план, но не измисля търсене, отзиви или изпитани продажби. MCP е по избор за предварително разрешени данни/действия с прочит обратно. Финалният тест оценява отделни случаи; качеството на собствения проект се сверява по рубриката.', sources=('lab','mcp'), title='Финален проект: доказателства, работещ прототип и версия 2')

exam('lm20-10', ('Свързваш нужда и позициониране.', 'Избираш честно послание.', 'Проверяваш права и допустим стек.'),
 'Прегледай М01–М04: конкретна нужда и момент; предложение и включено; доказателство за твърдение; права и цел на данните. При всяка грешка върни съответния урок и реши друг пример със същото правило.', 12, 10)
exam('lm20-11', ('Свързваш цена и принос.', 'Избираш полезен локален маршрут.', 'Проверяваш сайт, търсене и съдържание.'),
 'Прегледай М05–М10: приходи/разходи/капацитет; честни профил и отзиви; достъпна форма и получен запис; намерение в търсене; собствено доказателство. Сметни пример без подсказка и провери грешен знаменател.', 18, 15)
exam('lm20-12', ('Свързваш канал с действие.', 'Сравняваш качество и пълен разход.', 'Проверяваш данни и партньорски условия.'),
 'Прегледай М11–М16: материал с вярно обещание; Meta/Google цели и ограничения; уникални събития; отчет без причинно преувеличение; кампания с отговорник; партньорски пилот без купен отзив.', 18, 15)
exam('lm20-13', ('Проверяваш CRM действие и статус.', 'Приемаш полезен инструмент.', 'Спираш серия при промяна на нуждата.'),
 'Прегледай М17–М20: повторение и прочит обратно; предложен срещу резервиран час; формула и празен вход; имейл чернова срещу доставка; отказ и purchase stop; бюджет, принос и нов капацитет. Използвай предоставените факти, не измислен график.', 12, 10)
exam('lm20-14', ('Свързваш всички 20 модула.', 'Защитаваш решение по нов случай.', 'Познаваш границите на изпитния резултат.'),
 'Първо завърши предишните 13 урока в М20, включително четирите групови проверки. Финалът има 40 въпроса: групи М01–М04 (8), М05–М10 (12), М11–М16 (12), М17–М20 (8). Нужни са поне 32/40 и отделно минимум 60% във всяка група. Висок общ резултат не компенсира провалена група. При неуспех използвай показаната карта за преговор.', 40, 32, final=True)
